package com.lqq.supportflow.eventing.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper; import com.lqq.supportflow.eventing.FailedOutboxEvent; import com.lqq.supportflow.eventing.domain.*; import java.time.Instant; import java.util.List; import org.springframework.stereotype.Component;
@Component public class MyBatisOutboxAdapter implements OutboxPort { private static final int MAX_ATTEMPTS=8; private final OutboxMapper mapper; public MyBatisOutboxAdapter(OutboxMapper mapper){this.mapper=mapper;} public void record(Long tenantId,String eventType,String aggregateType,String aggregateId,String payload){OutboxEntity entity=new OutboxEntity();entity.tenantId=tenantId;entity.eventType=eventType;entity.aggregateType=aggregateType;entity.aggregateId=aggregateId;entity.payload=payload;entity.status="PENDING";entity.attemptCount=0;entity.nextAttemptAt=Instant.now();entity.createdAt=Instant.now();mapper.insert(entity);} public List<OutboxEvent> pending(int limit){Instant now=Instant.now();return mapper.selectList(new QueryWrapper<OutboxEntity>().eq("status","PENDING").and(wrapper->wrapper.isNull("next_attempt_at").or().le("next_attempt_at",now)).orderByAsc("created_at").last("LIMIT "+limit)).stream().map(entity->new OutboxEvent(entity.id,entity.tenantId,entity.eventType,entity.aggregateType,entity.aggregateId,entity.payload,entity.attemptCount,entity.createdAt)).toList();} public List<FailedOutboxEvent> failed(Long tenantId,int limit){return mapper.selectList(new QueryWrapper<OutboxEntity>().eq("tenant_id",tenantId).eq("status","FAILED").orderByDesc("failed_at").last("LIMIT "+limit)).stream().map(entity->new FailedOutboxEvent(entity.id,entity.eventType,entity.aggregateType,entity.aggregateId,entity.attemptCount,entity.lastError,entity.failedAt)).toList();} public void markPublished(Long eventId){mapper.update(new OutboxEntity(),new UpdateWrapper<OutboxEntity>().eq("id",eventId).eq("status","PENDING").set("status","PUBLISHED").set("published_at",Instant.now()).set("next_attempt_at",null).set("last_error",null).setSql("attempt_count = attempt_count + 1"));} public void recordFailure(Long eventId,String reason){OutboxEntity event=mapper.selectById(eventId);if(event==null||!"PENDING".equals(event.status))return;int attempts=event.attemptCount+1;Instant now=Instant.now();boolean exhausted=attempts>=MAX_ATTEMPTS;mapper.update(new OutboxEntity(),new UpdateWrapper<OutboxEntity>().eq("id",eventId).eq("status","PENDING").eq("attempt_count",event.attemptCount).set("attempt_count",attempts).set("last_error",reason).set("next_attempt_at",exhausted?null:now.plusSeconds(backoffSeconds(attempts))).set("failed_at",exhausted?now:null).set("status",exhausted?"FAILED":"PENDING"));} private long backoffSeconds(int attempts){return Math.min(3600L,1L<<Math.min(11,attempts));}}
